class MyCalendarThree {
    private java.util.TreeMap<Integer, Integer> map;

    public MyCalendarThree() {
        map = new java.util.TreeMap<>();
    }

    public int book(int start, int end) {
        map.merge(start, 1, Integer::sum);
        map.merge(end, -1, Integer::sum);
        int maxK = 0, active = 0;
        for (int val : map.values()) {
            active += val;
            maxK = Math.max(maxK, active);
        }
        return maxK;
    }
}

class MyCalendarThree {
    private java.util.Map<Integer, Integer> tree;
    private java.util.Map<Integer, Integer> lazy;

    public MyCalendarThree() {
        tree = new java.util.HashMap<>();
        lazy = new java.util.HashMap<>();
    }

    public int book(int start, int end) {
        update(start, end - 1, 0, 1000000000, 1);
        return tree.getOrDefault(1, 0);
    }

    private void update(int s, int e, int lo, int hi, int node) {
        if (s > hi || e < lo) return;
        if (s <= lo && hi <= e) {
            tree.put(node, tree.getOrDefault(node, 0) + 1);
            lazy.put(node, lazy.getOrDefault(node, 0) + 1);
            return;
        }
        int mid = lo + (hi - lo) / 2;
        update(s, e, lo, mid, 2 * node);
        update(s, e, mid + 1, hi, 2 * node + 1);
        tree.put(node, lazy.getOrDefault(node, 0) + Math.max(tree.getOrDefault(2 * node, 0), tree.getOrDefault(2 * node + 1, 0)));
    }
}
